def is_anagram(word1, word2):
    # Check if both words are of the same length
    if len(word1) != len(word2):
        return False

    # Check if both words contain only alphabetic characters
    if not all(char.lower() in 'abcdefghijklmnopqrstuvwxyz' for char in word1) or not all(char.lower() in 'abcdefghijklmnopqrstuvwxyz' for char in word2):
        return False

    # Sort the characters of both words and compare
    return sorted(word1.lower()) == sorted(word2.lower())
